// TypeScript definitions for the C3 type ComparisonProtocol

/**
 * @remarks this represents a value passed to a method that expects an instance of ComparisonProtocol
 */
declare interface IComparisonProtocol {
}

/**
 * @remarks this represents a made instance of ComparisonProtocol
 */
declare class ComparisonProtocol {

  lessThan(other: any): any;

  lessThanEqualTo(other: any): any;

  equalTo(other: any): any;

  notEqualTo(other: any): any;

  greaterThan(other: any): any;

  greaterThanEqualTo(other: any): any;
}

